              var li = document.createElement('li');
              li.innerHTML = '<span class="box-cat">' + esc(e.category) + '</span>' + esc(e.text) + ' <span class="box-meta">' + esc(e.date) + ' ' + esc(e.source) + (e.status && e.status !== 'open' ? ' [' + esc(e.status) + ']' : '') + (e.claimed_by ? ' claimed by ' + esc(e.claimed_by) : '') + '</span>';
